    resumo[[parameter]] = list(
      "media"   = apply( post[parameter][[1]], 2, mean          )                   ,
      "mediana" = apply( post[parameter][[1]], 2, stats::median )                   ,
      "hpd_min" = apply( hpd_temp, 2, function(x) { unlist(x) |&gt; purrr::pluck(1) }) ,
      "hpd_max" = apply( hpd_temp, 2, function(x) { unlist(x) |&gt; purrr::pluck(2) })
    )
}

