df_fit =
  resumo$S |&gt;
  cbind("tempo" = seq(0, max(isoladores$tempo), length.out = 100)) |&gt;
  as.data.frame()

km =
  survfit(
    Surv(tempo, evento) ~ 1,
    data = isoladores
  ) |&gt;
  broom::tidy()

ggplot(df_fit, aes(x = tempo, y = media)) +
  geom_ribbon(aes(ymin = hpd_min, ymax = hpd_max), alpha = 0.3) +
  geom_line(linewidth = 1) +
  geom_step(
    data = km,
    aes(x = time, y = estimate),
    color = "red",
    linewidth = 1,
    inherit.aes = FALSE
  ) +
  labs(x = "Tempo", y = "S(t)"
  ) +
  theme_minimal()















